-- Public Cat Parts Store references: marine cooling and lubrication systems.
-- Compatibility model names are copied only from the official Compatible Models sections.
-- No retail prices, inventory, or serial-specific fitment are inferred.
insert into public.part_catalog
(brand,part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,image_url,specifications,compatible_models,application_type,application_evidence,application_source_url)
values
('Caterpillar','282-5199','KIT-WATER PUMP','Auxiliary pump group kit. Cat Compatible Models lists Marine Auxiliary 3512C/3516C/3512B/3508B/3508C/3516B and Marine Engine 3512C/3512E/3508C/3508B/3516B/3516C/3512B/3516E; also industrial, engine, petroleum and gas applications.',ARRAY['3512C','3516C','3512B','3508B','3508C','3516B','3512E','3516E']::text[],'موتورهای دریایی - خنک‌کاری و پمپ آب','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/282-5199','Model names copied from official Compatible Models. Serial-specific fitment not inferred.','REFERENCE',null,'{}'::jsonb,ARRAY['3512C','3516C','3512B','3508B','3508C','3516B','3512E','3516E']::text[],'BOTH','Official Compatible Models lists Marine Auxiliary and Marine Engine plus industrial, engine, petroleum and gas applications.','https://parts.cat.com/en/catcorp/product/282-5199'),
('Caterpillar','8N-8466','PUMP GP-AUX','Auxiliary pump group. Cat Compatible Models lists Marine Engine and Marine Auxiliary 3508/3512/3516 families; also generator, industrial and gas-engine applications.',ARRAY['3512C','3516','3512','3508','3508C','3508B','3516B','3516C','3512B']::text[],'موتورهای دریایی - خنک‌کاری و پمپ کمکی','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/8N-8466','Model names copied from official Compatible Models.','REFERENCE',null,'{}'::jsonb,ARRAY['3512C','3516','3512','3508','3508C','3508B','3516B','3516C','3512B']::text[],'BOTH','Official Compatible Models lists Marine Engine and Marine Auxiliary plus generator, industrial and gas-engine applications.','https://parts.cat.com/en/catcorp/product/8N-8466'),
('Caterpillar','193-1468','KIT-AUXILIARY WATER PUMP INSTALL','Auxiliary water pump installation kit. Cat Compatible Models lists Marine Auxiliary and Marine Engine 3512C/3516B; generator-set, industrial, power-module and truck applications are also listed.',ARRAY['3512C','3516B']::text[],'موتورهای دریایی - خنک‌کاری و کیت پمپ','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/193-1468','Compatible model names copied from official public product page.','REFERENCE',null,'{}'::jsonb,ARRAY['3512C','3516B']::text[],'BOTH','Official Compatible Models lists Marine Auxiliary and Marine Engine and non-marine generator, industrial, power-module and truck applications.','https://parts.cat.com/en/catcorp/product/193-1468'),
('Caterpillar','9Y-5068','IMPELLER-AUX SEA WATER PUMP','Auxiliary Sea Water Pump Impeller for seawater circulation in marine cooling systems. Cat Compatible Models lists Marine Auxiliary and Marine Engine plus generator-set and petroleum applications.',ARRAY['3512B','3516B','3516','3512','3508B','3516C']::text[],'موتورهای دریایی - خنک‌کاری و ایمپلر آب دریا','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/9Y-5068','Official product title and Compatible Models section identify sea-water pump use and listed models.','REFERENCE',null,'{}'::jsonb,ARRAY['3512B','3516B','3516','3512','3508B','3516C']::text[],'BOTH','Official Compatible Models lists Marine Auxiliary/Marine Engine as well as Gen Set Engine, Generator Set and Petroleum Engine.','https://parts.cat.com/en/catcorp/product/9Y-5068'),
('Caterpillar','202-2175','KIT-AUXILIARY WATER PUMP INSTALL','Auxiliary water pump installation kit containing gaskets and seals. Cat Compatible Models lists Marine Engine and Marine Auxiliary 3508B/3516B/3512B and generator-set/industrial applications.',ARRAY['3508B','3516B','3512B']::text[],'موتورهای دریایی - خنک‌کاری و کیت پمپ','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/202-2175','Marine model names copied from official Compatible Models section.','REFERENCE',null,'{}'::jsonb,ARRAY['3508B','3516B','3512B']::text[],'BOTH','Official Compatible Models lists Marine Engine/Auxiliary and generator-set, industrial and locomotive applications.','https://parts.cat.com/en/catcorp/product/202-2175'),
('Caterpillar','291-4311','PUMP GP-AUX','Auxiliary water pump group; official Cat page marks the part discontinued. Marine Engine and Marine Auxiliary 3500-series models are listed alongside generator, industrial, locomotive and petroleum applications.',ARRAY['3512C','3516','3512','3508','3508C','3508B','3516B','3516C','3512B']::text[],'موتورهای دریایی - خنک‌کاری و پمپ کمکی','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/291-4311','Discontinued according to official Cat Parts Store page; retained as reference only.','REFERENCE',null,'{}'::jsonb,ARRAY['3512C','3516','3512','3508','3508C','3508B','3516B','3516C','3512B']::text[],'BOTH','Official Compatible Models lists Marine Engine/Auxiliary and generator, industrial, locomotive and petroleum applications.','https://parts.cat.com/en/catcorp/product/291-4311'),
('Caterpillar','318-2579','PUMP-AUX SEA WATER','Auxiliary Sea Water Pump circulates seawater through cooling systems. Cat Compatible Models lists Marine Engine and Marine Auxiliary plus generator-set, industrial, engine and petroleum applications.',ARRAY['3508','3512C','3516','3512','3508C','3508B','3516B','3516C','3512B']::text[],'موتورهای دریایی - خنک‌کاری و پمپ آب دریا','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/318-2579','Official product description explicitly identifies seawater circulation; model names copied from Compatible Models.','REFERENCE',null,'{}'::jsonb,ARRAY['3508','3512C','3516','3512','3508C','3508B','3516B','3516C','3512B']::text[],'BOTH','Official Compatible Models lists Marine Engine/Auxiliary plus generator-set, industrial, engine and petroleum applications.','https://parts.cat.com/en/catcorp/product/318-2579'),
('Caterpillar','284-1087','IMPELLER-AUX WATER PUMP','Auxiliary water pump impeller. Cat Compatible Models lists Marine Engine and Marine Auxiliary 3500-series models plus generator-set, industrial, engine and petroleum applications.',ARRAY['3512','3516','3508','3512C','3516C','3508C','3508B','3516B','3512B']::text[],'موتورهای دریایی - خنک‌کاری و ایمپلر پمپ','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/284-1087','Model names copied from official Compatible Models.','REFERENCE',null,'{}'::jsonb,ARRAY['3512','3516','3508','3512C','3516C','3508C','3508B','3516B','3512B']::text[],'BOTH','Official Compatible Models lists Marine Engine/Auxiliary and generator-set, industrial, engine and petroleum applications.','https://parts.cat.com/en/catcorp/product/284-1087'),
('Caterpillar','231-5127','PUMP-ENGINE OIL','Engine oil pump for lubrication system. Cat Compatible Models lists Marine Engine and Marine Auxiliary 3500-series models alongside generator, power-module, industrial, engine, locomotive and petroleum applications.',ARRAY['3508B','3516B','3516C','3512B','3512C']::text[],'موتورهای دریایی - روغن‌کاری و پمپ روغن','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/231-5127','Marine model names copied from official Compatible Models section.','REFERENCE',null,'{}'::jsonb,ARRAY['3508B','3516B','3516C','3512B','3512C']::text[],'BOTH','Official Compatible Models lists Marine Engine/Auxiliary and generator, power-module, industrial, engine, locomotive and petroleum applications.','https://parts.cat.com/en/catcorp/product/231-5127'),
('Caterpillar','231-6345','KIT-OIL PUMP','Oil pump kit. Cat Compatible Models lists Marine Engine 3508B/3512B/3512C and Marine Auxiliary 3512C/3512B plus industrial, engine and petroleum applications.',ARRAY['3508B','3512B','3512C']::text[],'موتورهای دریایی - روغن‌کاری و کیت پمپ روغن','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/231-6345','Marine model names copied from official Compatible Models section.','REFERENCE',null,'{}'::jsonb,ARRAY['3508B','3512B','3512C']::text[],'BOTH','Official Compatible Models lists Marine Engine/Auxiliary and industrial, engine and petroleum applications.','https://parts.cat.com/en/catcorp/product/231-6345'),
('Caterpillar','422-7389','KIT-EXTERNAL ENGINE OIL PUMP','External engine oil pump kit. Cat Compatible Models lists Marine Engine and Marine Auxiliary 3500-series models plus generator-set, power-module, petroleum, locomotive and gas-engine applications.',ARRAY['3512C','3508B','3516B','3516C','3512B']::text[],'موتورهای دریایی - روغن‌کاری و کیت پمپ','Cat Parts Store (official)','https://parts.cat.com/en/catcorp/product/422-7389','Marine model names copied from official Compatible Models section.','REFERENCE',null,'{}'::jsonb,ARRAY['3512C','3508B','3516B','3516C','3512B']::text[],'BOTH','Official Compatible Models lists Marine Engine/Auxiliary and generator-set, power-module, petroleum, locomotive and gas-engine applications.','https://parts.cat.com/en/catcorp/product/422-7389')
on conflict (part_number) do nothing;

-- Update records that may already exist from earlier catalog imports.
update public.part_catalog
set technical_group=case
 when part_number in ('282-5199','8N-8466','193-1468','9Y-5068','202-2175','291-4311','318-2579','284-1087') then 'موتورهای دریایی - خنک‌کاری و پمپ آب'
 when part_number in ('231-5127','231-6345','422-7389') then 'موتورهای دریایی - روغن‌کاری و پمپ روغن'
 else technical_group end,
 application_type='BOTH',
 application_evidence='Official Cat Compatible Models lists Marine Engine and/or Marine Auxiliary together with non-marine engine, generator, industrial, petroleum or other applications.',
 application_source_url='https://parts.cat.com/en/catcorp/product/'||part_number,
 updated_at=now()
where part_number in ('282-5199','8N-8466','193-1468','9Y-5068','202-2175','291-4311','318-2579','284-1087','231-5127','231-6345','422-7389');
